            for (int j = 0; j < columnCount(); ++j) {
                painter->drawPoint(i * cellWidth(), j * cellHeight(), QColor(255, 0, 0));
            }
        }
    }
};

class ZoomWidget : public QWidget
{
public:
    ZoomWidget(QWidget *parent) : QWidget(parent) {}

    void mousePressEvent(QMouseEvent *event)
    {
        startPosition = event->pos();
    }

    void mouseMoveEvent(QMouseEvent *event)
    {
        if (startPosition != QPoint()) {
            int deltaX = event->x() - startPosition.x();
            int deltaY = event->y() - startPosition.y();
            scaleFactor += deltaX / 100.0;
            if (scaleFactor < 0.1) {
                scaleFactor = 0.1;
            }
            update();
        }
    }

private:
    QPoint startPosition;
    double scaleFactor = 1.0;
};

