Here's a C++ program that implements the described functionality:

```cpp
#include <iostream>
#include <string>
#include <vector>

using namespace std;

// Recursive function to generate the Fibonacci sequence
vector<int> generateFibonacciSequence(int first, int second, int numElements) {
    if (numElements == 0) {
        return vector<int>();
    }

    vector<int> sequence = {first, second};
    for (int i = 2; i <= numElements; i++) {
        sequence.push_back(sequence[i - 1] + sequence[i - 2]);
    }

    return sequence;
}

// Function to prompt the user for input and handle errors
void getInput(int& first, int& second, int& numElements) {
    cout << "Enter the first two integers: ";
    cin >> first >> second;

    while (cin.fail() || first < 0 || second < 0) {
        cout << "Invalid input. Please enter two non-negative integers: ";
        cin.clear();
        cin.ignore(1000, '\n');
        cin >> first >> second;
    }

    cout << "Enter the number of sequence elements to generate: ";
    cin >> numElements;

    while (cin.fail() || numElements < 0) {
        cout << "Invalid input. Please enter a non-negative integer: ";
        cin.clear();
        cin.ignore(1000, '\n');
        cin >> numElements;
    }
}

int main() {
    int first, second, numElements;

    getInput(first, second, numElements);

    vector<int> sequence = generateFibonacciSequence(first, second, numElements);

    cout << "Generated sequence: ";
    for (int i = 0; i < sequence.size(); i++) {
        cout << sequence[i] << (i < sequence.size() - 1 ? ", " : "");
    }
    cout << endl;

    return 0;
}
