To solve this task, we will use a combination of regular expressions and a dictionary to replace the incorrect homophones with the correct ones. Here's a Swift function that does this:

```swift
import Foundation

func correctHomophones(in passage: String) -> String {
    let homophones = [
        "their": "there",
        "they're": "they are",
        "to": "too"
    ]

    let regex = try! NSRegularExpression(pattern: "(?<!\w)(\b\w+)\b", options: [])
    let matches = regex.matches(in: passage, options: [], range: NSRange(location: 0, length: passage.utf16.count))

    var correctedPassage = passage

    for match in matches {
        let word = (passage as NSString).substring(with: match.range)
        if let replacement = homophones[word] {
            correctedPassage = correctedPassage.replacingOccurrences(of: word, with: replacement)
        }
    }

    return correctedPassage
}

