Here's an example of how you can create a Google Apps Script that searches for a place name in a column, and stores the latitude and longitude in other columns:

```javascript
function searchPlace() {
  var sheet = SpreadsheetApp.getActiveSheet();
  var dataRange = sheet.getRange("A1:C10"); // Assuming your data is in columns A to C, rows 1 to 10
  var searchTerm = "New York"; // Replace this with the place name you want to search for

  var results = [];

  dataRange.forEach(function(row) {
    var address = row[0];
    var latitude = row[1];
    var longitude = row[2];

    if (address === searchTerm) {
      results.push({
        address: address,
        latitude: latitude,
        longitude: longitude
      });
    }
  });

  if (results.length > 0) {
    sheet.getRange("D1").setValue("Search Results");
    sheet.getRange("E1").setValue("Address");
    sheet.getRange("F1").setValue("Latitude");
    sheet.getRange("G1").setValue("Longitude");

    var headerRow = sheet.getRange("D1:G1");
    headerRow.setFontWeight("bold");

    var resultsRange = sheet.getRange("D2:G" + (results.length + 1));
    resultsRange.setValues(results);
  } else {
    sheet.getRange("D1").setValue("No results found.");
  }
}
```

This script will search for the place name "New York" in column A, and store the latitude and longitude in columns B and C respectively. The results will be displayed in a new table starting from row D. If no results are found, a message will be displayed in cell D1.

Here's the PHP custom function "smart_sort_array":

```php
function smart_sort_array($set, $order) {
    usort($set, function ($a, $b) use ($order) {
        return $order === 'asc' ? strcmp($a['age'], $b['age']) : strcmp($b['age'], $a['age']);
    });
    return $set;
}
```

