];

$order = 'asc'; // or 'desc' for descending order

$sorted_set = smart_sort_array($set, $order);

print_r($sorted_set);
```

```javascript
function getOptionEntries(dotNotatedString, key) {
  const entries = [];
  const splitArray = dotNotatedString.split('.');

  for (let i = 0; i < splitArray.length; i++) {
    const currentEntry = splitArray[i];
    const nextEntry = splitArray[i + 1];

    if (nextEntry) {
      const object = {};
      object[currentEntry] = entries;
      entries.push(object);
    } else {
      const obj = {};
      obj[key] = true;
      entries.push(obj);
    }
  }

  return entries;
}
```

