Here's a simple example of a toast notification using React Context:

```jsx
import React, { createContext, useEffect, useState } from 'react';

const ToastContext = createContext();

function ToastProvider({ children }) {
  const [toasts, setToasts] = useState([]);

  useEffect(() => {
    // Clear toasts after a certain time
    const timeout = setTimeout(() => {
      setToasts([]);
    }, 3000);

    return () => clearTimeout(timeout);
  }, [toasts]);

  function addToast(message) {
    setToasts((prevToasts) => [...prevToasts, message]);
  }

  return (
    <ToastContext.Provider value={{ addToast }}>
      {children}
    </ToastContext.Provider>
  );
}

function ToastConsumer() {
  const { addToast } = React.useContext(ToastContext);

  function handleClick() {
    addToast('This is a toast notification!');
  }

  return (
    <button onClick={handleClick}>Add Toast</button>
  );
}

function App() {
  return (
    <ToastProvider>
      <ToastConsumer />
    </ToastProvider>
  );
}

export default App;
```

In this example, we have a `ToastProvider` component that wraps the entire app and provides a `ToastContext` object with an `addToast` method. The `ToastConsumer` component consumes the `ToastContext` object and adds a toast notification when the "Add Toast" button is clicked. The toasts are displayed for 3 seconds before being cleared automatically.

